sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
if (!newValue) {
g_form.clearValue('department');
g_form.clearValue('email');
return;
}
var ga = new GlideAjax('HRCaseUserUtils');
ga.addParam('sysparm_name', 'getUserDetails');
ga.addParam('sysparm_caller_id', newValue);
ga.getXMLAnswer(function(answer) {
if (!answer) {
return;
}
var userDetails = JSON.parse(answer);
g_form.setValue(
'department',
userDetails.department
);
g_form.setValue(
'email',
userDetails.email
);
});
}
